  (s/keys :req-un [::metamodel-sync-repo/query
                   ::metamodel-sync-repo/componentTypeIds
                   ::metamodel-sync-repo/referenceTypeIds]))

(s/def ::create-global-field-body ::metamodel-sync-repo/global-field-create)
(s/def ::update-global-field-body ::metamodel-sync-repo/globalField)

(s/def ::sourceType (specs/string-with-limit? 500))
(s/def ::referenceType (specs/string-with-limit? 500))
(s/def ::targetType (specs/string-with-limit? 500))
(s/def ::rejected-suggestion (s/keys :req-un [::sourceType ::referenceType ::targetType]))
(s/def ::rejectedSuggestions (s/coll-of ::rejected-suggestion))
(s/def ::suggest-reference-types-body (s/keys :opt-un [::rejectedSuggestions]))

(s/def ::status string?)
(s/def ::recalculate-response (s/keys :req-un [::status]))

(def metamodel-sync-api
  (ring/router
   [["/global-field"
     ["" {:post {:name ::create-global-field
                 :parameters {:body ::create-global-field-body}
                 :handler create-global-field}
          :swagger {:public false}
          :conflicting true}]
     ["/:id" {:parameters {:path {:id ::specs/id}}}
      ["" {:put {:name ::update-global-field
                 :parameters {:body ::update-global-field-body}
                 :handler update-global-field}
           :delete {:name ::delete-global-field
                    :handler delete-global-field}
           :conflicting true}]
      ["/recalculate" {:post {:name ::recalculate-global-field
                              :handler recalculate-global-field
                              :responses {200 {:body ::recalculate-response}}}}]
      ["/usage" {:get {:name ::global-field-usage
                       :handler global-field-usage}}]]]
    ["/global-fields" {:get {:name ::global-fields
                             :handler global-fields}
                       :swagger {:public false}
                       :conflicting true}]
    ["/global-component-types"
     ["" {:get {:name ::global-component-types
                :handler global-component-types}
          :swagger {:public false}
          :conflicting true}]
     ["/:id/usage" {:get {:name ::global-component-type-usage
                          :parameters {:path {:id ::specs/id}}
                          :handler global-component-type-usage}
                    :swagger {:public false}}]]
    ["/implicit-references" {:get {:name ::implicit-references
                                   :handler implicit-references}
                             :swagger {:public false}
                             :conflicting true}]
    ["/suggest-reference-types" {:post {:name ::suggest-reference-types
                                        :parameters {:body ::suggest-reference-types-body}
                                        :handler suggest-reference-types}
                                 :swagger {:public false}
                                 :conflicting true}]
    ["/test-gremlin" {:post {:name ::test-gremlin
                             :parameters {:body ::test-gremlin-body}
                             :handler test-gremlin}
                      :swagger {:public false}
                      :conflicting true}]
    ["/:id" {:get {:name ::workspace-metamodel
                   :parameters {:path {:id ::specs/id}}
                   :handler get-metamodel}
             :put {:name ::update-workspace-metamodel
                   :parameters {:path {:id ::specs/id}
                                :body ::sync-workspace-metamodel-body}
                   :handler sync-metamodel}
             :swagger {:public false}
             :conflicting true}]]
   (assoc router/default-options :data {:swagger {:tags ["Metamodel Sync API"]}})))
