(defn change-reference-type
  [{{{:keys [referenceIds constraint]} :body} :parameters
    {:keys [metamodel-refactor-service]} :system
    :keys [ctx]
    :as req}]
  (->> {:allowed? (fn [_]
                    (crud-api/action-on-query-allowed?
                     reference-service/service-config
                     ctx
                     :update
                     (pq/by-ids referenceIds)))
        :processable? (fn [{:keys [::crud-api/instance]}]
                        (crud-api/processable?
                         metamodel-refactor-service/service-config ctx
                         {:action :convert-reference-type
                          :entity instance}))
        :post! (fn [{:keys [::crud-api/instance]}]
                 {::crud-api/result
                  (metamodel-refactor-service/change-reference-type!
                   metamodel-refactor-service ctx instance constraint)})}
       (merge crud-api/command-defaults)
       (liberator/run-resource req)))

(def metamodel-refactor-api
  (ring/router
   [["/to-date-field/:id" {:get {:name ::check-to-date-field
                                 :parameters {:path {:id ::specs/id}}
                                 :handler check-to-date-field}
                           :post {:name ::convert-to-date-field
                                  :parameters {:path {:id ::specs/id}
                                               :body ::to-date-field-body}
                                  :handler convert-to-date-field}}]
    ["/rename-field/:id" {:post {:name ::rename-field
                                 :parameters {:path {:id ::specs/id}
                                              :body ::rename-field-body}
                                 :handler rename-field}}]
    ["/change-reference-type" {:post {:name ::change-reference-type
                                      :parameters {:body ::change-reference-type-body}
                                      :handler change-reference-type}}]]
   (assoc router/default-options
          :data {:swagger {:tags ["Metamodel Refactor API"]}})))

